        private static PreflightInspectionPanel instance;private GameObject root;private RectTransform content;private Font font;
        public static void Open(){if(instance==null){GameObject g=new GameObject("ForgeBench_PreflightInspectionPanel");DontDestroyOnLoad(g);instance=g.AddComponent<PreflightInspectionPanel>();}instance.Show();}
        private void Awake(){if(instance!=null&&instance!=this){Destroy(gameObject);return;}instance=this;DontDestroyOnLoad(gameObject);font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");EnsureEventSystem();Build();root.SetActive(false);}private void Update(){if(root!=null&&root.activeSelf&&Input.GetKeyDown(KeyCode.Escape)&&!Application.isMobilePlatform)Close();}
        private void Show(){root.SetActive(true);Cursor.lockState=CursorLockMode.None;MobileInputState.Move=Vector2.zero;Refresh();}private void Close(){root.SetActive(false);Cursor.lockState=CursorLockMode.Locked;}
        private void Build(){root=new GameObject("PreflightRoot",typeof(RectTransform));root.transform.SetParent(transform,false);Canvas c=root.AddComponent<Canvas>();c.renderMode=RenderMode.ScreenSpaceOverlay;c.sortingOrder=25400;CanvasScaler sc=root.AddComponent<CanvasScaler>();sc.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;sc.referenceResolution=new Vector2(1920,1080);sc.matchWidthOrHeight=.5f;root.AddComponent<GraphicRaycaster>();GameObject bg=UI("BG",root.transform);Stretch(bg.GetComponent<RectTransform>());bg.AddComponent<Image>().color=new Color(.014f,.020f,.029f,.995f);GameObject panel=UI("Panel",bg.transform);RectTransform pr=panel.GetComponent<RectTransform>();pr.anchorMin=new Vector2(.055f,.05f);pr.anchorMax=new Vector2(.945f,.95f);pr.offsetMin=pr.offsetMax=Vector2.zero;panel.AddComponent<Image>().color=new Color(.052f,.064f,.08f,1f);GameObject header=UI("Header",panel.transform);RectTransform hr=header.GetComponent<RectTransform>();hr.anchorMin=new Vector2(0,1);hr.anchorMax=new Vector2(1,1);hr.pivot=new Vector2(.5f,1);hr.sizeDelta=new Vector2(0,84);hr.anchoredPosition=Vector2.zero;header.AddComponent<Image>().color=new Color(.072f,.087f,.105f,1f);Text title=Text("FINAL ACCEPTANCE / PREFLIGHT",header.transform,30,TextAnchor.MiddleLeft,Color.white);RectTransform tr=title.rectTransform;tr.anchorMin=new Vector2(.025f,0);tr.anchorMax=new Vector2(.68f,1);tr.offsetMin=tr.offsetMax=Vector2.zero;Button refresh=Button("RE-SCAN",header.transform,new Color(.10f,.43f,.64f,1f),Refresh);RectTransform rr=refresh.GetComponent<RectTransform>();rr.anchorMin=new Vector2(.72f,.16f);rr.anchorMax=new Vector2(.87f,.84f);rr.offsetMin=rr.offsetMax=Vector2.zero;Button close=Button("✕",header.transform,new Color(.55f,.11f,.12f,1f),Close);RectTransform xr=close.GetComponent<RectTransform>();xr.anchorMin=new Vector2(.91f,.16f);xr.anchorMax=new Vector2(.975f,.84f);xr.offsetMin=xr.offsetMax=Vector2.zero;GameObject scrollGo=UI("Scroll",panel.transform);RectTransform sr=scrollGo.GetComponent<RectTransform>();sr.anchorMin=new Vector2(.02f,.025f);sr.anchorMax=new Vector2(.98f,.90f);sr.offsetMin=sr.offsetMax=Vector2.zero;ScrollRect scroll=scrollGo.AddComponent<ScrollRect>();scroll.horizontal=false;scroll.scrollSensitivity=42f;GameObject viewport=UI("Viewport",scrollGo.transform);Stretch(viewport.GetComponent<RectTransform>());viewport.AddComponent<Image>().color=new Color(.024f,.032f,.042f,.78f);Mask mask=viewport.AddComponent<Mask>();mask.showMaskGraphic=false;scroll.viewport=viewport.GetComponent<RectTransform>();GameObject body=UI("Content",viewport.transform);content=body.GetComponent<RectTransform>();content.anchorMin=new Vector2(0,1);content.anchorMax=new Vector2(1,1);content.pivot=new Vector2(.5f,1);content.sizeDelta=new Vector2(0,500);VerticalLayoutGroup vg=body.AddComponent<VerticalLayoutGroup>();vg.padding=new RectOffset(20,20,18,22);vg.spacing=10;vg.childControlHeight=true;vg.childForceExpandHeight=false;vg.childControlWidth=true;vg.childForceExpandWidth=true;ContentSizeFitter fit=body.AddComponent<ContentSizeFitter>();fit.verticalFit=ContentSizeFitter.FitMode.PreferredSize;scroll.content=content;}
        private void Refresh(){if(content==null)return;for(int i=content.childCount-1;i>=0;i--)Destroy(content.GetChild(i).gameObject);GameRuntime g=GameRuntime.Instance;JobState j=g?.ActiveJob;MachineState m=g?.ActiveMachine;Heading("FINAL ACCEPTANCE INSPECTION",j==null?"No active contract":j.jobId+" · "+j.customerName+" · "+j.title);if(g==null||j==null||m==null){Card("NOT READY","An active contract and device are required.",new Color(.95f,.32f,.22f,1f));return;}PreflightReport report=new PreflightInspectionService(g).Inspect(j,m);Color result=report.pass?new Color(.20f,.84f,.48f,1f):new Color(.95f,.30f,.22f,1f);Card(report.Summary,"Acceptance quality "+report.qualityScore.ToString("0")+" / 100 · blocking "+report.blocking+" · warnings "+report.warnings+"\nThis inspection is read-only: it does not auto-repair or silently satisfy requirements.",result);Section("BLOCKING FINDINGS");foreach(InspectionFinding f in report.findings.Where(x=>x.severity==InspectionSeverity.Blocking))Card(f.system,f.message,new Color(.98f,.34f,.24f,1f));if(report.blocking==0)Card("NONE","No blocking finding detected by the current preflight rules.",new Color(.20f,.84f,.48f,1f));Section("WARNINGS");foreach(InspectionFinding f in report.findings.Where(x=>x.severity==InspectionSeverity.Warning))Card(f.system,f.message,new Color(.96f,.69f,.22f,1f));if(report.warnings==0)Card("NONE","No advisory warning.",new Color(.20f,.84f,.48f,1f));Section("TRACEABILITY");foreach(InspectionFinding f in report.findings.Where(x=>x.severity==InspectionSeverity.Info))Card(f.system,f.message,Color.white);if(report.pass){Button submit=Button(SpecialistJobService.IsSpecialist(j)?"OPEN SPECIALIST CONTRACT BOARD":"OPEN JOB BOARD",content,new Color(.10f,.56f,.38f,1f),()=>{Close();if(SpecialistJobService.IsSpecialist(j))SpecialistContractBoard.Open();else g.UI?.OpenTab("JOBS");});submit.gameObject.AddComponent<LayoutElement>().preferredHeight=60;}}
        private void Heading(string a,string b){Text t=Block(a,32,Color.white,55);t.fontStyle=FontStyle.Bold;Block(b,19,new Color(.56f,.65f,.73f,1f),38);}private void Section(string a){Text t=Block(a,22,new Color(.10f,.64f,.92f,1f),42);t.fontStyle=FontStyle.Bold;}private void Card(string title,string sub,Color c){GameObject g=UI("Card",content);g.AddComponent<Image>().color=new Color(.095f,.115f,.145f,1f);VerticalLayoutGroup v=g.AddComponent<VerticalLayoutGroup>();v.padding=new RectOffset(18,18,11,12);v.spacing=4;v.childControlHeight=true;v.childForceExpandHeight=false;Text a=Text(title,g.transform,21,TextAnchor.MiddleLeft,c);a.fontStyle=FontStyle.Bold;if(!string.IsNullOrEmpty(sub)){Text b=Text(sub,g.transform,17,TextAnchor.UpperLeft,new Color(.66f,.73f,.80f,1f));b.horizontalOverflow=HorizontalWrapMode.Wrap;b.verticalOverflow=VerticalWrapMode.Overflow;}}private Text Block(string value,int size,Color c,float height){Text t=Text(value,content,size,TextAnchor.MiddleLeft,c);LayoutElement l=t.gameObject.AddComponent<LayoutElement>();l.preferredHeight=height;return t;}private Button Button(string label,Transform p,Color c,Action a){GameObject g=UI("Button_"+label,p);Image i=g.AddComponent<Image>();i.color=c;Button b=g.AddComponent<Button>();b.targetGraphic=i;if(a!=null)b.onClick.AddListener(()=>a());Text t=Text(label,g.transform,16,TextAnchor.MiddleCenter,Color.white);Stretch(t.rectTransform,5);t.raycastTarget=false;return b;}private Text Text(string value,Transform p,int size,TextAnchor align,Color c){GameObject g=UI("Text",p);Text t=g.AddComponent<Text>();t.font=font;t.text=value;t.fontSize=size;t.alignment=align;t.color=c;t.raycastTarget=false;return t;}private GameObject UI(string n,Transform p){GameObject g=new GameObject(n,typeof(RectTransform));g.transform.SetParent(p,false);return g;}private static void Stretch(RectTransform r,float i=0){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=new Vector2(i,i);r.offsetMax=new Vector2(-i,-i);}private static void EnsureEventSystem(){if(FindAnyObjectByType<EventSystem>()!=null)return;GameObject e=new GameObject("EventSystem");e.AddComponent<EventSystem>();e.AddComponent<StandaloneInputModule>();DontDestroyOnLoad(e);}
    }
